// Typed Scala facade for tau2-bench domain 'mock' — the FIXED, committed
// tool surface the agent calls. Generated by gen_tools.py; regenerate the
// committed facades after a tau2 upgrade with:  ./regen_facades.sh
// (which overwrites these files). Each function dispatches to the in-scope
// tau2 tool via Tau.callTool.

val facadeDomain: String = "mock"

/** Create a new task for a user. */
def createTask(userId: String, title: String, description: Option[String] = None): String =
  val args = ujson.Obj()
  args("user_id") = ujson.Str(userId)
  args("title") = ujson.Str(title)
  description.foreach(v => args("description") = ujson.Str(v))
  Tau.callTool("create_task", args)

/** Get all users in the database. */
def getUsers(): String = Tau.callTool("get_users")

/** Update the status of a task. */
def updateTaskStatus(taskId: String, status: String): String =
  val args = ujson.Obj()
  args("task_id") = ujson.Str(taskId)
  args("status") = ujson.Str(status)
  Tau.callTool("update_task_status", args)

/** Transfer the user to a human agent, with a summary of the user's issue. Only transfer if - the user explicitly asks for a human agent - given the policy and the available tools, you cannot solve the user's issue. */
def transferToHumanAgents(summary: String): String =
  val args = ujson.Obj()
  args("summary") = ujson.Str(summary)
  Tau.callTool("transfer_to_human_agents", args)

/** Call this function when you are done with the task. */
def done(): String = Tau.callTool("done")

/** Data types + tool signatures for the agent prompt. */
val domainToolsDoc: String =
  """- createTask(userId: String, title: String, description: Option[String] = None): String  — Create a new task for a user.
- getUsers(): String  — Get all users in the database.
- updateTaskStatus(taskId: String, status: String): String  — Update the status of a task.
- transferToHumanAgents(summary: String): String  — Transfer the user to a human agent, with a summary of the user's issue. Only transfer if - the user explicitly asks for a human agent - given the policy and the available tools, you cannot solve the user's issue.
- done(): String  — Call this function when you are done with the task."""
